INSERT INTO _migration_624_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bece_intsci_s3_033', 'topic_bece_science_agric', 'subj_bece_science', 'exam_bece', NULL, NULL, 'State two benefits a farmer gets by processing fresh cassava into gari before storage.', 'short_answer', NULL, NULL, 'Any two of: drying and roasting remove moisture, so the gari keeps much longer without rotting; gari is lighter and easier to transport; processing adds value, so it sells at a higher price; proper processing reduces harmful compounds in fresh cassava.', 'Fresh cassava roots contain a lot of water and start to rot within a few days. Processing them into gari removes most of the moisture through pressing, fermentation and roasting, so the product stores for months; the dried gari is lighter and cheaper to transport to market; processing adds value and raises the selling price; and proper roasting reduces the harmful cyanide compounds in fresh cassava. Any two of these benefits earn the marks.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_034', 'topic_bece_science_agric', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A farmer sows 200 maize seeds and 170 of them germinate. Calculate the germination percentage.', 'calculation', NULL, NULL, '85%', 'Germination percentage = (number of seeds germinated ÷ number of seeds sown) × 100 = (170 ÷ 200) × 100 = 0.85 × 100 = 85%. Answer: the germination percentage is 85%.', 'easy', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_035', 'topic_bece_science_agric', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A JHS class wants to start a small vegetable garden behind the school block.', 'structured', NULL, NULL, '(a) Any two of: fertile, well-drained soil; a reliable source of water for irrigation; enough sunlight; closeness to the school so the crops are easy to tend and safe from thieves and animals (1 each). (b) Clearing removes weeds that would compete with the vegetables for nutrients, water and light, and digging loosens the soil so that roots, air and water can enter easily (1). (c) Records of costs and sales show whether the garden is making a profit or a loss (1); records of what was planted and how each crop performed help the class plan better for the next season (1).', '(a) Any two of: fertile, well-drained soil; a reliable source of water for irrigation; enough sunlight; closeness to the school so the crops are easy to tend and safe from thieves and animals (1 each). (b) Clearing removes weeds that would compete with the vegetables for nutrients, water and light, and digging loosens the soil so that roots, air and water can enter easily (1). (c) Records of costs and sales show whether the garden is making a profit or a loss (1); records of what was planted and how each crop performed help the class plan better for the next season (1).', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'State', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_036', 'topic_bece_science_health', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Health workers advise that pit latrines and refuse dumps should be sited far away from wells and streams. Why is this important?', 'multiple_choice', NULL, '["A. Waste near water attracts snakes that bite people","B. The smell of the waste makes the water too salty to drink","C. Germs from the waste can seep into or be washed into the water and cause diseases such as cholera","D. Pit latrines dug near wells always collapse into the water"]', 'C', 'Faeces and refuse contain disease-causing micro-organisms. Rain can wash these germs into streams, and they can seep through the soil into wells; people who drink the contaminated water may suffer from cholera, typhoid or dysentery. (Snakes and smell are not the main health reason for the rule, and the advice concerns contamination, not collapsing pits.) Therefore the correct answer is C: Germs from the waste can seep into or be washed into the water and cause diseases such as cholera.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_037', 'topic_bece_science_health', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Covering water storage containers and draining standing water around the home helps to control malaria mainly because it...', 'multiple_choice', NULL, '["A. kills the malaria parasites already inside the mosquitoes","B. stops mosquitoes from flying at night","C. makes the stored water too cold for drinking","D. removes the places where mosquitoes lay their eggs and breed"]', 'D', 'Mosquitoes lay their eggs in stagnant water, where the larvae develop into adults. Removing or covering such water breaks the mosquito life cycle, so fewer adult mosquitoes survive to bite people and spread the malaria parasite. (It does not kill parasites already inside mosquitoes, and adult mosquitoes can still fly at night.) Therefore the correct answer is D: removes the places where mosquitoes lay their eggs and breed.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_038', 'topic_bece_science_health', 'subj_bece_science', 'exam_bece', NULL, NULL, 'State two methods a family can use to make unsafe drinking water safe at home.', 'short_answer', NULL, NULL, 'Any two of: boiling the water; filtering it and then treating it with the recommended amount of chlorine; using solar disinfection in clear bottles left in the sun.', 'Boiling water for a few minutes kills the germs that cause diseases such as cholera and typhoid. Filtering removes particles, and adding the recommended small amount of chlorine then kills the remaining germs. Solar disinfection — leaving clear bottles of water in bright sunshine for several hours — also kills many germs. Any two of these methods earn the marks.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec');
INSERT INTO _migration_624_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_bece_intsci_s3_035_a', 'q_bece_intsci_s3_035', 'a', 'State two factors the class should consider when choosing the site for the garden.', '2', 'Any two of: fertile, well-drained soil; a reliable source of water for irrigation; enough sunlight; closeness to the school so the crops are easy to tend and safe from thieves and animals (1 each).', '1'),
('sqp_q_bece_intsci_s3_035_b', 'q_bece_intsci_s3_035', 'b', 'Give one reason why the land is cleared and dug before planting.', '1', 'Clearing removes weeds that would compete with the vegetables for nutrients, water and light, and digging loosens the soil so that roots, air and water can enter easily (1).', '2'),
('sqp_q_bece_intsci_s3_035_c', 'q_bece_intsci_s3_035', 'c', 'State two reasons for keeping records of the garden activities.', '2', 'Records of costs and sales show whether the garden is making a profit or a loss (1); records of what was planted and how each crop performed help the class plan better for the next season (1).', '3');
INSERT INTO _migration_624_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_624_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_624_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_624_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_624_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_624_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_624_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_624_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_624_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_624_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_624_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_624_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
